"""Generate Rust HTTP request-body limits from the Python contract owner."""
from __future__ import annotations

import argparse

from codex_http_body_limits import (
    ASSET_BODY_LIMIT,
    ASSET_PATHS,
    DEFAULT_BODY_LIMIT,
    PROJECTS_BODY_LIMIT,
    PROJECTS_PATHS,
    VOICE_AUDIO_BODY_LIMIT,
    VOICE_AUDIO_PATHS,
)
from codex_layout import REPOSITORY_ROOT


OUTPUT = (
    REPOSITORY_ROOT
    / "workspaces/runtime/packages/runtime-http/src/http_body_limits_generated.rs"
)


def render_rust_http_body_limits() -> str:
    lines = [
        "//! Generated by `studio_api.generate_http_body_limits`; do not edit.",
        "//! Source: `codex_http_body_limits.py`.",
        f"pub(crate) const DEFAULT_BODY_LIMIT: usize = {DEFAULT_BODY_LIMIT:_};",
        f"pub(crate) const ASSET_BODY_LIMIT: usize = {ASSET_BODY_LIMIT:_};",
        f"pub(crate) const VOICE_AUDIO_BODY_LIMIT: usize = {VOICE_AUDIO_BODY_LIMIT:_};",
        f"pub(crate) const PROJECTS_BODY_LIMIT: usize = {PROJECTS_BODY_LIMIT:_};",
        "",
        "pub(crate) fn request_limit(path: &str) -> usize {",
        "    if studio_runtime_services::federation_limits::FEDERATION_PATHS.contains(&path) {",
        "        return studio_runtime_services::federation_limits::FEDERATION_BODY_LIMIT;",
        "    }",
        "    match path {",
    ]
    for paths, constant in (
        (ASSET_PATHS, "ASSET_BODY_LIMIT"),
        (VOICE_AUDIO_PATHS, "VOICE_AUDIO_BODY_LIMIT"),
        (PROJECTS_PATHS, "PROJECTS_BODY_LIMIT"),
    ):
        for path in sorted(paths):
            lines.append(f'        "{path}" => {constant},')
    lines.extend(("        _ => DEFAULT_BODY_LIMIT,", "    }", "}", ""))
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write the generated Rust contract")
    mode.add_argument("--check", action="store_true", help="verify the generated Rust contract")
    args = parser.parse_args()

    expected = render_rust_http_body_limits()
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_text(encoding="utf-8") != expected:
            raise SystemExit(f"{OUTPUT.relative_to(REPOSITORY_ROOT)} is stale; run http-body-limits:generate")
        return 0
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
